-- User-authorized cumulative Version History update. No application or operational data changes.
begin;
lock table public.training_app_versions,public.training_app_version_changes in share row exclusive mode;
do $guard$
begin
 if exists(select 1 from public.training_app_versions where is_current and version not in ('2.1.30','2.1.31')) then
  raise exception 'A different release is current. Review Version History before applying this update.';
 end if;
end $guard$;
update public.training_app_versions set is_current=false,updated_at=now() where is_current=true and version<>'2.1.31';
insert into public.training_app_versions(version,release_date,title,summary,is_current,initial_problem,fix_summary,verification_summary)
values('2.1.31','2026-11-23','Agency Business Rules and Sign-in Improvements','Cumulative release-history update for improvements delivered after v2.1.30: clearer catalog and report sections, improved Saved items formatting, easier agency assignments, optional details, Unassign, available counts, tool descriptions, and a Show password slider. Also records earlier account, agency overview/logo, PDF progress, and platform updates that were not yet included in Version History.',true,'Version History had not been updated beyond v2.1.30. Catalog items and report sections were difficult to scan; staff had to select tools individually, complete mandatory assignment details, and reopen saved tools for editing. There was no direct Unassign action or available-tool count, and tool descriptions were not shown in the assignment workspace.','Organized catalog and reports by item type with distinct headers and counts; improved saved-item formatting; added Add All Tools, optional source/retention/unit fields, always-visible saved assignments, Unassign, available counts, and brief description previews. Replaced the login visibility button with a Show password slider. This cumulative entry also records previously delivered staff-account recovery, agency cards/overviews/logos, PDF cover/progress, and platform recovery updates.','TypeScript and production build checks passed for the recent merged changes. Component checks verified bulk selection, draft preservation, optional fields, saved-assignment visibility, agency isolation, Unassign confirmation/cancel, and error handling. Transaction-rollback database checks verified optional metadata, validation, atomic saves, stale-update protection, exact unassignment, reassignment, and role restrictions; test fixtures were rolled back. PDF checks covered grouping, continuation headers, missing items, and blank/partial metadata. The Saved items update passed JSX and rendered-content checks; its local browser visual preview was blocked by the execution environment. Earlier changes and their test records were reviewed from merged repository PRs; mailbox delivery, fresh image generation, and background-job execution were not re-tested for this history update. Latest feature deployment: dpl_CkdJN7sRa7sEny8Mo3ACXz95FqSn, commit 85283d3d06497e15b0bfc653e54c1a970deeb2b9, verified READY in Production.')
on conflict(version) do update set release_date=excluded.release_date,title=excluded.title,summary=excluded.summary,is_current=true,initial_problem=excluded.initial_problem,fix_summary=excluded.fix_summary,verification_summary=excluded.verification_summary,updated_at=now();
delete from public.training_app_version_changes where version_id=(select id from public.training_app_versions where version='2.1.31');
insert into public.training_app_version_changes(version_id,component,change_summary,sort_order)
select v.id,c.component,c.summary,c.ordinal from public.training_app_versions v cross join (values
('Login','Added a keyboard-accessible Show password slider. Passwords start hidden, and toggling visibility preserves the entered value.',1),
('Item Catalog','Grouped saved items and the existing-item selector by Tool, Dashboard, Smart Tool, and Misc., with alphabetical names and category counts.',2),
('Catalog Sections','Added prominent colored section headers: navy for Tool, teal for Dashboard, purple for Smart Tool, and slate for Misc.',3),
('Saved Items','Introduced individual item cards with larger names, Edit item actions, labeled Description and Expected outcome areas, a total count, and stacked details on smaller screens. Saved wording and paragraph breaks are preserved.',4),
('Add All Tools','Added Add All Tools to the Agency for all unassigned catalog items, including items outside the search filter. Existing assignments and drafts are preserved; saves support batches of up to 100.',5),
('Optional Assignment Details','Made Data Source, Retention, and Unit optional. New selections start blank, and existing details can be cleared. Supplied values still receive validation.',6),
('Saved Assignments','Show the selected agency’s saved tools immediately in Assignment details and keep them visible after saving or cancelling an edit.',7),
('Unassign','Added Unassign beside Edit for saved assignments. Confirmation identifies the tool and agency; removal preserves the catalog item and assignments to other agencies. The item can be assigned again.',8),
('Available Tool Count','Added the available count beside Add tools, matching Assigned. Counts update with saved changes and remain independent of the search filter.',9),
('Tool Description Previews','Display two-line previews beneath tool names in Add tools, Assigned, and Assignment details, with the complete saved description available on hover.',10),
('Agency Business Rules Report','Group the on-screen report and PDF by item type with colored headings, counts, and alphabetical items. PDF group headings repeat on continued pages. Blank assignment details display as Not specified.',11),
('Assignment Safeguards','Preserve agency isolation, manager permissions, the 100-item save limit, atomic saves, and stale-edit checks. Unassign also checks the agency, assignment ID, and expected update timestamp.',12),
('Agency Directory and Overview','Earlier delivered improvements placed existing agencies first in responsive cards with tool counts and clear actions, separated the create/edit form, and added agency-specific overview headings, introductions, and key features to reports and PDFs.',13),
('Agency Logos and PDF Progress','Earlier delivered improvements added private PNG/JPG logo upload and report embedding, a fresh cinematic cover request during PDF export, and a visible progress panel with cover/PDF stages, spinner, elapsed time, and retryable errors.',14),
('Catalog Editing and Shared Controls','Earlier delivered improvements added selection of existing catalog items, unique item-name checks across types, alphabetical assignment lists, clearer button hover/focus contrast, and emphasized report data sources.',15),
('Staff Passwords and Account Recovery','Earlier delivered improvements added self-service password changes, required replacement of temporary passwords, account emails with temporary credentials, and verified email recovery handling.',16),
('Database and Background Jobs','Earlier repository releases rebuilt the unavailable database in the replacement Backtrace project and enabled explicitly approved background email processing, expired-class closing, and manager reminders. The rebuild notes state that prior operational records, users, and uploaded files were not recovered.',17)
) c(component,summary,ordinal) where v.version='2.1.31';
commit;
